496	    // ---------- helpers ----------
497	
498	    private record CreateCmd(String commandKey, String batchKey, String productCode, String batchNo,
499	                             Instant producedAt, List<String> requiredTests) {
500	    }
501	
502	    private String unique() {
503	        return UUID.randomUUID().toString().substring(0, 8);
504	    }
505	
506	    private String createBody(String batchKey, List<String> items) throws Exception {
507	        return objectMapper.writeValueAsString(new CreateCmd("CK-1", batchKey, "PROD-1", "LOT-1",
508	                Instant.parse("2026-01-02T03:04:05Z"), items));
509	    }
510	
511	    private void createBatch(String batchKey, List<String> items, int expectedStatus) throws Exception {
512	        mockMvc.perform(post("/api/batches")
513	                        .contentType(MediaType.APPLICATION_JSON).content(createBody(batchKey, items)))
514	                .andExpect(status().is(expectedStatus));
515	    }
516	
517	    private String testReq(String testKey, String item, String result, String inspector) throws Exception {
518	        return objectMapper.writeValueAsString(new TestCmd("CK-T-" + unique(), testKey, item, result, inspector));
519	    }
520	
521	    private record TestCmd(String commandKey, String testKey, String testItem, String result,
522	                           String inspector) {
523	    }
524	
525	    private void submitTest(String batchKey, String body, Object unused1, Object unused2, int expected)
526	            throws Exception {
527	        mockMvc.perform(post("/api/batches/" + batchKey + "/tests")
528	                        .contentType(MediaType.APPLICATION_JSON).content(body))
529	                .andExpect(status().is(expected));
530	    }
531	
532	    private void approve(String batchKey, String actor, String role, String commandKey, int expected)
533	            throws Exception {
534	        mockMvc.perform(post("/api/batches/" + batchKey + "/approvals")
535	                        .header("X-Actor-Id", actor).header("X-Approval-Role", role)
536	                        .contentType(MediaType.APPLICATION_JSON)
537	                        .content("{\"commandKey\":\"" + commandKey + "\"}"))
538	                .andExpect(status().is(expected));
539	    }
540	
541	    private void recall(String batchKey, String actor, String reason, String commandKey, int expected)
542	            throws Exception {
543	        mockMvc.perform(post("/api/batches/" + batchKey + "/recall")
544	                        .header("X-Actor-Id", actor)
545	                        .contentType(MediaType.APPLICATION_JSON)
546	                        .content("{\"commandKey\":\"" + commandKey + "\",\"reason\":\"" + reason + "\"}"))
547	                .andExpect(status().is(expected));
548	    }
