551	        MvcResult result = mockMvc.perform(get("/api/batches/" + batchKey + "/history"))
552	                .andExpect(status().isOk()).andReturn();
553	        return objectMapper.readTree(result.getResponse().getContentAsString())
554	                .path("batch").path("status").asText();
555	    }
