557	    private List<String> availableKeys() throws Exception {
558	        MvcResult result = mockMvc.perform(get("/api/batches/available"))
559	                .andExpect(status().isOk()).andReturn();
560	        JsonNode array = objectMapper.readTree(result.getResponse().getContentAsString());
561	        List<String> keys = new ArrayList<>();
562	        array.forEach(n -> keys.add(n.path("batchKey").asText()));
563	        return keys;
