import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 登记包装计划请求。plannedQuantity 为正整数；[labelStart, labelEnd] 为连续标签号段（两端含）。
 */
public record RegisterPlanRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "plannedQuantity 不能为空")
        @Positive(message = "plannedQuantity 必须为正整数") Integer plannedQuantity,
        @NotNull(message = "labelStart 不能为空")
        @PositiveOrZero(message = "labelStart 不能为负数") Long labelStart,
        @NotNull(message = "labelEnd 不能为空")
        @PositiveOrZero(message = "labelEnd 不能为负数") Long labelEnd
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 包装计划响应：计划包装数量与连续标签号段（两端含）。
 */
public record PackagingPlanResponse(
        String batchKey,
        int plannedQuantity,
        long labelStart,
        long labelEnd,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量封箱请求：一次提交 1～100 条封箱记录；任一标签校验失败整次回滚，不留下部分占用。
 */
public record SealBoxesRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "seals 不能为空")
        @Size(min = 1, max = 100, message = "seals 必须包含 1～100 条封箱记录")
        List<@Valid SealSpec> seals
) {
    /**
     * 单条封箱记录：一个标签号对应一个封箱，封箱数量为正整数。
     */
    public record SealSpec(
            @NotBlank(message = "sealKey 不能为空") String sealKey,
            @NotNull(message = "labelNo 不能为空") Long labelNo,
            @NotNull(message = "quantity 不能为空")
            @Positive(message = "quantity 必须为正整数") Integer quantity
    ) {
    }
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 封箱记录响应。voidedAt/voidReason 仅作废后有值，活跃记录为 null。
 */
public record SealResponse(
        String batchKey,
        String sealKey,
        long labelNo,
        int quantity,
        String status,
        int version,
        Instant createdAt,
        Instant voidedAt,
        String voidReason
) {
}

